Object.assign(SNIP,{});PRESET_NOTES["l2"]={"Ví dụ: UCLN bằng Euclid": "Mỗi vòng thay (a, b) bằng (b, a mod b). So các giá trị a, b, r trong khung Hình động với bảng theo dõi ở mục 2.4.", "Ví dụ: UCLN bằng cách thử từng ước": "Cách “ngây thơ”: thử d từ số nhỏ hơn giảm dần tới khi d chia hết cả hai. Đúng, nhưng số bước có thể gần bằng min(a, b). So bộ đếm bước với ví dụ Euclid, rồi thử nhập 1000000007 1000000009.", "Ví dụ: Giải phương trình bậc nhất": "Mã giả: nếu a = 0 thì (nếu b = 0 thì vô số nghiệm, ngược lại vô nghiệm), ngược lại x = -b / a. Mỗi “nếu” thành một if; nhánh lồng nhau thành if lồng nhau.", "Ví dụ: Đảo ngược các chữ số": "Mã giả: dao ← 0; trong khi n > 0 làm (dao ← dao × 10 + n mod 10; n ← n div 10). Theo dõi dao lớn dần 5, 54, 543, 5432, 54321.", "Ví dụ: Số lớn nhất trong ba số": "Thay vì so sánh mọi cặp với nhiều if lồng nhau, giữ “lớn nhất tạm thời” m và so lần lượt với từng số: cách viết ngắn và dễ mở rộng cho n số."};EX_HINTS["l2"]=[["Viết hàm ucln theo mã giả Euclid ở mục 2.1.", "BCNN có thể tới khoảng 10^18: dùng long long.", "Tính a / g * b (chia trước rồi nhân) để giá trị trung gian không vượt long long."], ["Làm đúng theo mã giả trong code mẫu.", "Các số 0 ở cuối n (như 1200) tự biến mất vì 0 · 10 + 0 vẫn là 0."], ["a = 0 là trường hợp đặc biệt: phương trình thành 0 = -b.", "Chia số thực: -(double)b / a (nếu chia hai số int sẽ mất phần thập phân).", "Bẫy: với b = 0, -0.0 / 5 cho -0.0 và in ra -0.00. Thêm if (x == 0) x = 0; để in 0.00."]];
/* ===================== BÀI 2 · Mô tả giải thuật bằng các bước, mã giả và lưu đồ ===================== */
/* Bài 2 · Mô tả giải thuật bằng các bước, mã giả và lưu đồ
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR2=[{label:"Ví dụ: UCLN bằng Euclid",input:"48 18",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long a, b;\n    cin >> a >> b;\n    while (b != 0) {\n        long long r = a % b;\n        a = b;\n        b = r;\n    }\n    cout << \"UCLN = \" << a << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["a","b","r"]}],py:{code:"a, b = map(int, input().split())\nwhile b != 0:\n    r = a % b\n    a = b\n    b = r\nprint(\"UCLN =\", a)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] s = Console.ReadLine().Split();\n        long a = long.Parse(s[0]);\n        long b = long.Parse(s[1]);\n        while (b != 0)\n        {\n            long r = a % b;\n            a = b;\n            b = r;\n        }\n        Console.WriteLine(\"UCLN = \" + a);\n    }\n}"}},{label:"Ví dụ: UCLN bằng cách thử từng ước",input:"48 18",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long a, b;\n    cin >> a >> b;\n    long long d = a < b ? a : b;\n    while (a % d != 0 || b % d != 0) {\n        d--;\n    }\n    cout << \"UCLN = \" << d << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["a","b","d"]}],py:{code:"a, b = map(int, input().split())\nd = a if a < b else b\nwhile a % d != 0 or b % d != 0:\n    d -= 1\nprint(\"UCLN =\", d)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] s = Console.ReadLine().Split();\n        long a = long.Parse(s[0]);\n        long b = long.Parse(s[1]);\n        long d = a < b ? a : b;\n        while (a % d != 0 || b % d != 0)\n        {\n            d--;\n        }\n        Console.WriteLine(\"UCLN = \" + d);\n    }\n}"}},{label:"Ví dụ: Giải phương trình bậc nhất",input:"2 -5",code:"#include <iostream>\n#include <iomanip>\nusing namespace std;\n\nint main() {\n    double a, b;\n    cin >> a >> b;\n    if (a == 0) {\n        if (b == 0) cout << \"VO SO NGHIEM\\n\";\n        else cout << \"VO NGHIEM\\n\";\n    } else {\n        double x = -b / a;\n        cout << fixed << setprecision(2) << x << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"vars",names:["a","b","x"]}],py:{code:"a, b = map(float, input().split())\nif a == 0:\n    if b == 0:\n        print(\"VO SO NGHIEM\")\n    else:\n        print(\"VO NGHIEM\")\nelse:\n    x = -b / a\n    print(f\"{x:.2f}\")",note:"Mã giả nhiều nhánh chuyển thành if / else lồng nhau. f\"{x:.2f}\" in x với đúng 2 chữ số thập phân."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] s = Console.ReadLine().Split();\n        double a = double.Parse(s[0]);\n        double b = double.Parse(s[1]);\n        if (a == 0)\n        {\n            if (b == 0) Console.WriteLine(\"VO SO NGHIEM\");\n            else Console.WriteLine(\"VO NGHIEM\");\n        }\n        else\n        {\n            double x = -b / a;\n            Console.WriteLine(x.ToString(\"F2\"));\n        }\n    }\n}"}},{label:"Ví dụ: Đảo ngược các chữ số",input:"12345",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    long long dao = 0;\n    while (n > 0) {\n        dao = dao * 10 + n % 10;\n        n /= 10;\n    }\n    cout << dao << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["n","dao"]}],py:{code:"n = int(input())\ndao = 0\nwhile n > 0:\n    dao = dao * 10 + n % 10\n    n //= 10\nprint(dao)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n        long dao = 0;\n        while (n > 0)\n        {\n            dao = dao * 10 + n % 10;\n            n /= 10;\n        }\n        Console.WriteLine(dao);\n    }\n}"}},{label:"Ví dụ: Số lớn nhất trong ba số",input:"7 19 4",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a, b, c;\n    cin >> a >> b >> c;\n    int m = a;\n    if (b > m) m = b;\n    if (c > m) m = c;\n    cout << m << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["a","b","c","m"]}],py:{code:"a, b, c = map(int, input().split())\nm = a\nif b > m:\n    m = b\nif c > m:\n    m = c\nprint(m)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] s = Console.ReadLine().Split();\n        int a = int.Parse(s[0]), b = int.Parse(s[1]), c = int.Parse(s[2]);\n        int m = a;\n        if (b > m) m = b;\n        if (c > m) m = c;\n        Console.WriteLine(m);\n    }\n}"}}];
