makeEx2(document.getElementById("ex-l2"),sim2,[{t:"UCLN và BCNN",d:"Đầu vào: hai số nguyên dương a, b (≤ 10^9). Đầu ra: ước chung lớn nhất và bội chung nhỏ nhất của a và b, cách nhau một dấu cách. Gợi ý: BCNN(a, b) = a / UCLN(a, b) × b.",tests:[{in:"48 18",out:"6 144"},{in:"7 13",out:"1 91"},{in:"12 12",out:"12 12"},{in:"1000000000 999999999",out:"1 999999999000000000"},{in:"1 1",out:"1 1"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long a, b;\n    cin >> a >> b;\n    // Euclid tìm UCLN, rồi tính BCNN\n    return 0;\n}",perf:{gen:n=>"1000000007 "+(n*1000+7),ns:[1000,100000,10000000],need:"logn",limit:n=>400,why:"Thử từng ước có thể cần tới hàng tỷ bước. Giải thuật Euclid chỉ cần vài chục vòng lặp."},py:{start:"a, b = map(int, input().split())\n# Euclid tìm UCLN, rồi tính BCNN",hints:["Viết hàm ucln theo mã giả Euclid ở mục 2.1.","BCNN = a // g * b. Dùng // để kết quả là số nguyên.","Python có sẵn math.gcd, nhưng hãy tự viết để luyện giải thuật."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] s = Console.ReadLine().Split();\n        long a = long.Parse(s[0]);\n        long b = long.Parse(s[1]);\n        // Euclid tìm UCLN, rồi tính BCNN\n    }\n}",hints:["Viết hàm static long Ucln(long a, long b) theo mã giả Euclid ở mục 2.1.","BCNN có thể tới khoảng 10^18: dùng long.","Tính a / g * b (chia trước rồi nhân) để giá trị trung gian không vượt long."]}},{t:"Đảo ngược số",d:"Đầu vào: số nguyên dương n (≤ 10^9). Đầu ra: số nhận được khi viết các chữ số của n theo thứ tự ngược lại (bỏ các số 0 ở đầu nếu có).",tests:[{in:"12345",out:"54321"},{in:"1200",out:"21"},{in:"7",out:"7"},{in:"1000000000",out:"1"},{in:"907",out:"709"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    // dao <- 0; trong khi n > 0: dao <- dao * 10 + n mod 10; n <- n div 10\n    return 0;\n}",py:{start:"n = int(input())\n# dao <- 0; trong khi n > 0: dao <- dao * 10 + n mod 10; n <- n div 10",hints:["Làm đúng theo mã giả trong code mẫu; “div” trong Python là //.","Các số 0 ở cuối n (như 1200) tự biến mất vì 0 · 10 + 0 vẫn là 0."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n        // dao <- 0; trong khi n > 0: dao <- dao * 10 + n mod 10; n <- n div 10\n    }\n}",hints:["Làm đúng theo mã giả trong code mẫu.","Các số 0 ở cuối n (như 1200) tự biến mất vì 0 · 10 + 0 vẫn là 0."]}},{t:"Phương trình bậc nhất",d:"Đầu vào: hai số nguyên a, b. Giải phương trình ax + b = 0. Đầu ra: VO NGHIEM, VO SO NGHIEM, hoặc nghiệm x với đúng 2 chữ số thập phân.",tests:[{in:"2 -5",out:"2.50"},{in:"0 3",out:"VO NGHIEM"},{in:"0 0",out:"VO SO NGHIEM"},{in:"5 0",out:"0.00"},{in:"-4 2",out:"0.50"},{in:"3 1",out:"-0.33"}],start:"#include <iostream>\n#include <iomanip>\nusing namespace std;\n\nint main() {\n    int a, b;\n    cin >> a >> b;\n    // nếu a = 0 thì ..., ngược lại x = -b / a\n    return 0;\n}",py:{start:"a, b = map(int, input().split())\n# nếu a = 0 thì ..., ngược lại x = -b / a",hints:["a = 0 là trường hợp đặc biệt: phương trình thành 0 = -b.","Trong Python, / luôn cho số thực; in 2 chữ số thập phân bằng f\"{x:.2f}\".","Bẫy: với b = 0, -0 / 5 cho -0.0 và in ra -0.00. Thêm if x == 0: x = 0.0 để in 0.00."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] s = Console.ReadLine().Split();\n        int a = int.Parse(s[0]), b = int.Parse(s[1]);\n        // nếu a = 0 thì ..., ngược lại x = -b / a\n    }\n}",hints:["a = 0 là trường hợp đặc biệt: phương trình thành 0 = -b.","Chia số thực: -(double)b / a (chia hai số int sẽ mất phần thập phân).","In đúng 2 chữ số thập phân bằng x.ToString(\"F2\"). Bẫy: với b = 0, -0.0 / 5 cho -0.0 và in ra -0.00; thêm if (x == 0) x = 0; để in 0.00."]}}]);

makeQuiz("quiz2","score2",[{"q": "Trong lưu đồ, hình thoi biểu diễn gì?", "o": ["Bắt đầu hoặc kết thúc", "Nhập hoặc xuất dữ liệu", "Câu hỏi đúng/sai (rẽ nhánh)", "Tính toán, gán giá trị"], "a": 2, "e": "Hình thoi là khối điều kiện, có hai mũi tên ra cho hai trường hợp đúng và sai."}, {"q": "Mã giả <code>x ← x + 1<\/code> tương ứng với lệnh C++ nào?", "o": ["<code>x == x + 1;<\/code>", "<code>x = x + 1;<\/code>", "<code>x + 1 = x;<\/code>", "<code>cin &gt;&gt; x;<\/code>"], "a": 1, "e": "Mũi tên ← là phép gán: tính vế phải rồi lưu vào biến bên trái."}, {"q": "Chạy Euclid với a = 20, b = 8. Sau vòng lặp đầu tiên, (a, b) là?", "o": ["(8, 4)", "(8, 2)", "(4, 0)", "(12, 8)"], "a": 0, "e": "r = 20 mod 8 = 4, rồi a ← 8, b ← 4."}, {"q": "Vì sao nên chạy tay một giải thuật với ví dụ nhỏ trước khi lập trình?", "o": ["Để chương trình chạy nhanh hơn", "Để phát hiện sớm sai sót trong ý tưởng, trước khi tốn công viết code", "Vì máy tính không chạy được mã giả", "Không cần thiết"], "a": 1, "e": "Bảng theo dõi giúp kiểm tra ý tưởng với chi phí thấp; sửa giải thuật trên giấy dễ hơn sửa code."}]);

